window.BibliotecaPeriodPanel=function(cap,target){const DATA=window.BIBLIOTECA_PM25_PERIODS;const $=()=>target;const MONTHS=["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];const fmt=n=>n==null?'—':n.toLocaleString('es-CL',{minimumFractionDigits:1,maximumFractionDigits:2});function periodPanel(cap){
const periods=DATA.periods[cap],current=periods.find(p=>p.year===2026),previous=periods.find(p=>p.year===2025);
const comparable=[current,previous].every(p=>p?.value!=null&&!p.insufficientMonths.length);
const delta=comparable?current.value-previous.value:null,pct=comparable&&previous.value>0?100*delta/previous.value:null;
const signed=v=>(v>0?'+':'')+fmt(v),monthText=p=>p.insufficientMonths.map(m=>MONTHS[m-1]).join(', ');
const historical=periods.filter(p=>p.year>=2013&&p.year<=2025&&p.value!=null&&!p.insufficientMonths.length);
const historicMean=historical.length?historical.reduce((a,p)=>a+p.value,0)/historical.length:null;
const stationsChanged=current.stationIdsUsed.join(',')!==previous.stationIdsUsed.join(',');
$('periodComparison').innerHTML=`<div class="charthead"><div><h2>Enero–agosto: el mismo período</h2><p class="sub">${cap} · 2026 frente a 2025 · medias calculadas desde los datos diarios</p></div><span class="badge">Corte: 31 de agosto</span></div><div class="metrics">${[previous,current].map(p=>`<div class="metric"><span class="sub">Enero–agosto de ${p.year}</span><strong>${fmt(p.value)} <small style="display:inline">µg/m³</small></strong><small>${p.classification} · ${fmt(p.coveragePct)}% de cobertura (${p.daysWithData}/${p.daysInPeriod} días)</small><small>${p.stationsWithData} estaciones · ${p.insufficientMonths.length?'Meses bajo 75%: '+monthText(p):'Los 8 meses cumplen ≥75% de cobertura'}</small></div>`).join('')}<div class="metric"><span class="sub">Cambio entre períodos equivalentes</span><strong>${delta==null?'No comparable':signed(delta)+' µg/m³'}</strong><small>${pct==null?'Sin porcentaje publicable':signed(pct)+'% respecto de enero–agosto de 2025'}</small><small>${comparable?'La diferencia no atribuye causas.':'Se exige ≥75% de cobertura en cada uno de los 8 meses de ambos años.'}</small></div></div><p class="note" style="padding-top:16px">Contexto histórico enero–agosto de 2013–2025: <b>${fmt(historicMean)} µg/m³</b>, media de ${historical.length} períodos con los 8 meses utilizables (un peso igual por año). ${stationsChanged?'Las estaciones que aportan datos cambian entre 2025 y 2026; interpretar la diferencia con cautela.':'La lista de estaciones coincide, pero su aporte diario puede variar.'} ${[current,previous].some(p=>p.classification!=='validado')?'Incluye datos preliminares, sujetos a revisión.':''}</p><details style="margin:0 28px 20px"><summary>Cobertura por estación y años del contexto</summary><p class="sub">Años: ${historical.map(p=>p.year).join(', ')}. Cada número junto a una estación indica sus días con datos incluidos.</p>${[previous,current].map(p=>`<p class="sub">${p.year}: ${Object.entries(p.stationDays).map(([id,n])=>'estación '+id+': '+n+'/'+p.daysInPeriod+' días').join(' · ')||'Sin datos'}</p>`).join('')}</details>`;
}

periodPanel(cap);};
